#!/usr/bin/env bash
# Shared helpers for the scripts in /opt/app/bin. Sourced, not executed.

APP_DIR=/opt/app
STATE_DIR=$APP_DIR/state
RUNTIME_DIR=$APP_DIR/runtime
LOG_DIR=/var/log/app

log() { echo "[$(basename "$0")] $(date -u +%Y-%m-%dT%H:%M:%SZ) $*"; }
die() { log "ERROR: $*" >&2; exit 1; }

# Exports every value from settings.env (generated by Terraform) into the environment.
load_settings() {
  [ -f "$APP_DIR/settings.env" ] || die "$APP_DIR/settings.env is missing"
  set -a
  # shellcheck source=/dev/null
  source "$APP_DIR/settings.env"
  set +a
  mkdir -p "$STATE_DIR" "$RUNTIME_DIR" "$LOG_DIR"
  chmod 700 "$RUNTIME_DIR"
}

# docker compose with this project's files, env files and (for local MongoDB) profile.
compose() {
  local profile_args=()
  if [ "$DB_MODE" = "local" ]; then
    profile_args=(--profile local-db)
  fi
  docker compose \
    --project-name app \
    --project-directory "$APP_DIR" \
    --file "$APP_DIR/docker-compose.yml" \
    --env-file "$APP_DIR/settings.env" \
    --env-file "$RUNTIME_DIR/compose.env" \
    "${profile_args[@]}" "$@"
}
